3	/// A package name validated to be safe for use as a filesystem path
4	/// segment (no traversal, no absolute-path prefixes) and well-formed
5	/// enough to send upstream.
6	#[derive(Debug, Clone)]
7	pub struct PackageName {
8	    raw: String,
9	    /// The unscoped portion — for `@scope/name` this is `name`, for
10	    /// `name` this is the whole thing. Used to validate tarball
11	    /// filenames, which are always `<basename>-<version>.tgz`.
12	    basename: String,
13	}
14	
15	impl PackageName {
16	    pub fn parse(raw: &str) -> Result<Self, RegistryError> {
17	        let invalid = || RegistryError::InvalidPackageName { name: raw.to_string() };
18	        if raw.is_empty() || raw.len() > 214 {
19	            return Err(invalid());
20	        }
21	        let basename = if let Some(rest) = raw.strip_prefix('@') {
22	            let (scope, name) = rest.split_once('/').ok_or_else(invalid)?;
23	            if !is_safe_segment(scope) || !is_safe_segment(name) {
24	                return Err(invalid());
25	            }
26	            name.to_string()
27	        } else {
28	            if !is_safe_segment(raw) {
29	                return Err(invalid());
30	            }
31	            raw.to_string()
32	        };
33	        Ok(Self { raw: raw.to_string(), basename })
34	    }
35	
36	    pub fn as_str(&self) -> &str {
37	        &self.raw
38	    }
39	
40	    pub fn tarball_name_for_version(&self, version: &str) -> String {
41	        format!("{}-{version}.tgz", self.basename)
42	    }
43	
44	    /// Validate `filename` and return the canonical disk filename
45	    /// (`<basename>-<version>.tgz`). Used by the publish handler so
46	    /// libnpmpublish's `@scope/name-1.0.0.tgz` attachment lands on
47	    /// disk under the same path the GET endpoint serves.
48	    pub fn canonicalize_tarball_name(&self, filename: &str) -> Result<String, RegistryError> {
49	        self.parse_tarball_name(filename).map(|(canonical, _)| canonical)
50	    }
51	
52	    /// Like [`Self::canonicalize_tarball_name`] but also returns the
53	    /// version segment extracted from the filename. The publish
54	    /// handler uses the version to look up `versions[v].dist` and
55	    /// verify the tarball's integrity against what the packument
56	    /// declares.
57	    pub fn parse_tarball_name(&self, filename: &str) -> Result<(String, String), RegistryError> {
58	        let invalid = || RegistryError::InvalidTarballName {
59	            package: self.raw.clone(),
60	            filename: filename.to_string(),
61	        };
62	        let stem = filename.strip_suffix(".tgz").ok_or_else(invalid)?;
63	        // Try the longer prefix first so that for an unscoped package
64	        // (where `self.raw == self.basename`) we still match.
65	        let rest = stem
66	            .strip_prefix(&self.raw)
67	            .or_else(|| stem.strip_prefix(&self.basename))
68	            .ok_or_else(invalid)?;
69	        let version = rest.strip_prefix('-').ok_or_else(invalid)?;
70	        if !is_safe_segment(version) {
71	            return Err(invalid());
72	        }
73	        Ok((self.tarball_name_for_version(version), version.to_string()))
74	    }
75	}
76	
77	fn is_safe_segment(segment: &str) -> bool {
78	    !segment.is_empty()
79	        && !segment.starts_with('.')
80	        && !segment.contains('/')
81	        && !segment.contains('\\')
82	        && !segment.contains('\0')
83	        && segment != ".."
84	}
