11	/// Build an [`Upstream`] pointing at `url` with `headers`, all per-uplink
12	/// tuning knobs at their verdaccio defaults.
13	fn upstream(url: String, headers: HeaderMap) -> Upstream {
14	    Upstream::new("npmjs", &UplinkConfig::with_defaults(url, headers))
15	}
16	
17	/// Fixed "current time" for abbreviation tests so the `time`-map
18	/// coarsening (which buckets entries by age) is deterministic.
19	fn now() -> DateTime<Utc> {
20	    Utc.with_ymd_and_hms(2024, 3, 20, 12, 0, 0).unwrap()
21	}
22	
23	/// Build a header map carrying a bearer `Authorization` plus one
24	/// custom header — the resolved per-uplink set an [`Upstream`] is
25	/// expected to attach to every request.
26	fn auth_and_custom_headers() -> HeaderMap {
27	    let mut headers = HeaderMap::new();
28	    headers.insert(AUTHORIZATION, HeaderValue::from_static("Bearer secret-token"));
29	    headers.insert("x-org", HeaderValue::from_static("acme"));
30	    headers
31	}
