147	async fn fetch_packument_304_without_validators_is_an_error() {
148	    let mut server = mockito::Server::new_async().await;
149	    // No conditional header is sent (empty validators), so a `304` here is
150	    // a misbehaving upstream — there's no body and nothing to revalidate
151	    // against. It must surface as an error, not a `NotModified` that the
152	    // caller could mistake for "keep serving the cache".
153	    let mock = server
154	        .mock("GET", "/foo")
155	        .match_header("if-none-match", mockito::Matcher::Missing)
156	        .match_header("if-modified-since", mockito::Matcher::Missing)
157	        .with_status(304)
158	        .expect(1)
159	        .create_async()
160	        .await;
161	
162	    let upstream = upstream(server.url(), HeaderMap::new());
163	    let name = PackageName::parse("foo").unwrap();
164	    let result = upstream.fetch_packument(&name, &CacheValidators::default()).await;
165	
166	    assert!(result.is_err(), "an unconditional 304 must not be treated as NotModified");
167	    mock.assert_async().await;
168	}
