/// any query string (`?…`) and URL fragment (`#…`) stripped. Returns
/// `None` for a URL that ends in a trailing slash or otherwise has no
/// usable last segment.
///
/// The returned slice borrows from `url`. The input need not be an
/// absolute URL: a bare relative basename (`foo-1.0.0.tgz`, no host) is a
/// valid input and returns itself.
pub fn tarball_basename(url: &str) -> Option<&str> {
    // The path ends at the first `?` or `#`, whichever comes first.
    let path = url.split(['?', '#']).next().unwrap_or(url);
    let basename = path.rsplit('/').next().unwrap_or(path);
